import os, sys, re, argparse, datetime, shutil
from pathlib import Path

def load_source_config(filename):
    """Read the small [[sources]] subset of TTDL's TOML configuration."""
    p = Path(filename)
    if not p.exists(): return []
    entries=[]; current=None
    for raw in p.read_text(encoding='utf-8').splitlines():
        line=raw.split('#',1)[0].strip()
        if line == '[[sources]]':
            current={}; entries.append(current); continue
        if current is None or '=' not in line: continue
        k,v=(x.strip() for x in line.split('=',1))
        if v.lower() in ('true','false'): val=v.lower()=='true'
        elif len(v)>=2 and v[0] in ('"', "'") and v[-1]==v[0]: val=v[1:-1]
        else: continue
        current[k]=val
    return entries

VERSION='Terminal Todo List Manager(TTDL) Version 6.1.1'

def parse(line, ident=1):
    from parser import parse_todo
    t=parse_todo(line,ident)

    return {'id':t.id,'raw':t.raw,'done':t.done,'pri':t.priority or '', 'priority':t.priority or '', 'created':t.created or '',
            'finished':t.completed or '', 'completed':t.completed or '', 'due':t.due or '', 'threshold':t.threshold or '', 'rec':t.rec or '', 'subject':t.subject,
            'projects':t.project,'contexts':t.context,'project':t.project,'context':t.context,
            'hashtag':t.hashtag,'tags':t.tags,'tag':t.tags,'timer':(t.tags.get('tmr') or [None])[0],'hidden':t.hidden}


